// o arquivo contém os bytes 0123456
int a = open("f", O_RDONLY);
int b = dup(a);                 // mesma entrada de arquivo aberto que a
int c = open("f", O_RDONLY);    // entrada nova, offset 0
char buf[2], x, y;
read(a, buf, 2);                // buf = '0','1'; o offset compartilhado agora é 2
read(b, &x, 1);                 // x = '2', porque o offset é compartilhado
read(c, &y, 1);                 // y = '0', porque c tem offset próprio
